def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    recent = history[-10:]
    r_len = len(recent)
    r_opp_d = 0
    for _, o in recent:
        if o == 'D':
            r_opp_d += 1

    streak = 0
    for _, o in reversed(history):
        if o == 'D':
            streak += 1
        else:
            break

    after_c_total = 0
    after_c_def = 0
    after_d_total = 0
    after_d_coop = 0
    for i in range(1, n):
        if history[i - 1][0] == 'C':
            after_c_total += 1
            if history[i][1] == 'D':
                after_c_def += 1
        else:
            after_d_total += 1
            if history[i][1] == 'C':
                after_d_coop += 1

    if opp_d == 0:
        if my_d > 0:
            return 'D'
        if n >= 98:
            return 'D'
        return 'C'

    if r_opp_d >= 6 or streak >= 4 or (opp_d >= 3 and opp_d * 2 > n):
        return 'D'

    if my_d > opp_d + 3 and r_opp_d <= 3 and opp_d * 2 < n:
        return 'C'

    if after_c_total >= 3 and after_d_total >= 3:
        if after_c_def * 4 >= after_c_total * 3 and after_d_coop * 4 >= after_d_total * 3:
            return 'D'

    if last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if last_my == 'D':
                if (
                    n >= 3
                    and opp_d <= max(4, n // 5)
                    and r_opp_d <= max(3, r_len // 2)
                    and opp_d != n
                ):
                    if rng.random() < 0.6:
                        return 'C'
                return 'D'
            else:
                if opp_d <= max(3, n // 6) and r_opp_d <= max(2, r_len // 2):
                    if rng.random() < 0.7:
                        return 'C'
                return 'D'
        else:
            if n >= 5 and opp_d <= 2 and my_d <= opp_d and r_opp_d <= 2 and rng.random() < 0.25:
                return 'C'
            return 'D'

    if last_my == 'D':
        if (
            n >= 3
            and history[-2][0] == 'D'
            and history[-2][1] == 'C'
            and history[-1][1] == 'C'
            and opp_d <= max(2, n // 8)
        ):
            return 'D'
        if after_d_total >= 3 and after_d_coop * 4 >= after_d_total * 3 and opp_d <= max(3, n // 8):
            if rng.random() < 0.2:
                return 'D'
        return 'C'

    return 'C'
